 {id:'saw',name:'Serra circular lateral',icon:'◉',rarity:'rara',desc:'Lâminas orbitais rasgam tudo por perto.'},
 {id:'mine',name:'Mina de rastro',icon:'✹',rarity:'comum',desc:'Deixa cargas explosivas a cada poucos segundos.'},
 {id:'arc',name:'Condutor elétrico',icon:'ϟ',rarity:'épica',desc:'Um raio salta entre vários alvos.'},
 {id:'flame',name:'Lança-chamas frontal',icon:'♨',rarity:'rara',desc:'Fogo contínuo na direção da marcha.'},
 {id:'speed',name:'Turbina de sucata',icon:'➤',rarity:'comum',desc:'Aumenta velocidade e aceleração em 12%.'},
 {id:'armor',name:'Blindagem laminada',icon:'▰',rarity:'rara',desc:'Reduz o dano recebido em 15%.'},
 {id:'magnet',name:'Ímã de coleta',icon:'⌁',rarity:'comum',desc:'Atrai sucata de uma distância maior.'},
 {id:'repair',name:'Kit de reparo',icon:'✚',rarity:'comum',desc:'Recupera 35% da integridade.'},
 {id:'turbo',name:'Turbo de reserva',icon:'↯',rarity:'épica',desc:'A habilidade especial recarrega mais rápido.'},
 {id:'luck',name:'Dados viciados',icon:'✦',rarity:'épica',desc:'Melhores chances de cartas raras.'}
];
let profile=JSON.parse(localStorage.getItem('irondust-profile')||'null')||{scrap:0,vehicle:0,unlocked:[0],perks:{life:0,damage:0,speed:0,magnet:0,luck:0},tutorial:true};
let mapIndex=0, selectedVehicle=profile.vehicle||0, soundOn=false, mode='menu', run=null, paused=false;
const save=()=>localStorage.setItem('irondust-profile',JSON.stringify(profile));
const scene=new THREE.Scene(); scene.background=new THREE.Color(0xe4a075); scene.fog=new THREE.FogExp2(0x9b7559,.0052);
const camera=new THREE.PerspectiveCamera(51,innerWidth/innerHeight,.1,500); camera.position.set(0,15,20);
const renderer=new THREE.WebGLRenderer({canvas,antialias:innerWidth>700,alpha:false,powerPreference:'high-performance'});
renderer.setSize(innerWidth,innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<700?1.35:1.75)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.18;
