 const maxSpeed=(profile.vehicle===1?22:profile.vehicle===4?13:17)*(1+run.speedBonus+profile.perks.speed*.025);car.speed+=throttle*(throttle>0?13:9)*dt;car.speed*=Math.pow(drifting?.975:.91,dt*60);car.speed=clamp(car.speed,-maxSpeed*.48,maxSpeed);const steerScale=.42+Math.min(1,Math.abs(car.speed)/maxSpeed)*.95;car.heading+=steer*steerScale*dt*(drifting?1.65:1)*(car.speed<-.2?-1:1);car.drifting=drifting;
