 if(Math.abs(car.speed)>3&&Math.random()<dt*12){const rear=car.root.position.clone().add(new THREE.Vector3(0,.15,1.6).applyAxisAngle(new THREE.Vector3(0,1,0),car.heading));makeDust(rear,drifting?0xc79262:0x9d7353,drifting?.55:.32)}
