  if(dist<d.radius+1.6){if(d.boss){if(d.attack<=0){hurtPlayer(d.damage);d.attack=1.5}}else if(d.attack<=0){hurtPlayer(d.damage);d.attack=1.1;e.position.addScaledVector(delta.normalize(),-2)}}if(d.boss&&dist<24&&d.attack<.25&&Math.random()<.25){const target=car.root.position.clone().add(new THREE.Vector3(0,1,0));makeProjectile(e.position.clone().add(new THREE.Vector3(0,1.4,0)),target,'rocket',10);d.attack=2.3}}
 for(const b of [...bullets]){const u=b.userData;u.life-=dt;b.position.addScaledVector(u.dir,dt*(u.kind==='rocket'?30:65));if(u.kind==='rocket'){const target=enemies.find(e=>e.position.distanceTo(b.position)<e.userData.radius+1);if(target){const p=b.position.clone();for(const e of [...enemies])if(e.position.distanceTo(p)<6)damageEnemy(e,u.damage);makeBurst(p,0xff783e,15,1.4);scene.remove(b);bullets.splice(bullets.indexOf(b),1);continue}}else if(u.kind==='bullet'){const target=enemies.find(e=>e.position.distanceTo(b.position)<e.userData.radius);if(target){damageEnemy(target,u.damage);makeBurst(b.position,0xffc66e,2,.55);scene.remove(b);bullets.splice(bullets.indexOf(b),1);continue}}if(u.life<=0){scene.remove(b);bullets.splice(bullets.indexOf(b),1)}}
