 for(const m of [...decals]){m.userData.life-=dt;const target=enemies.find(e=>e.position.distanceTo(m.position)<2.4);if(target){const p=m.position.clone();for(const e of [...enemies])if(e.position.distanceTo(p)<4)damageEnemy(e,m.userData.damage);makeBurst(p,0xff672f,12,1);m.userData.life=0}if(m.userData.life<=0){scene.remove(m);decals.splice(decals.indexOf(m),1)}}
 for(const p of [...particles]){const u=p.userData;u.life-=dt;if(u.kind==='light'){p.intensity*=.82}else{p.position.x+=u.vx*dt;p.position.y+=u.vy*dt;p.position.z+=u.vz*dt;u.vy-=dt*(u.kind==='dust'?1.5:5);p.material.opacity=Math.max(0,u.life/u.max);p.scale.multiplyScalar(u.kind==='dust'?1+dt*.3:1)}if(u.life<=0){scene.remove(p);particles.splice(particles.indexOf(p),1)}}
