function endRun(won){if(!run)return;const result={won,time:run.time,kills:run.kills,scrap:run.scrap,level:run.level};paused=true;$('#overlayCard').innerHTML=`<span class="section-kicker">${won?'EXPEDIÇÃO CONCLUÍDA':'VEÍCULO DESTRUÍDO'}</span><h2>${won?'VOCÊ SOBREVIVEU.':'FIM DE ESTRADA.'}</h2><p>${won?'O deserto vai lembrar seu nome.':'A horda tomou o setor. O ferro recuperado é seu.'}</p><div class="result-stats"><span>TEMPO <b>${Math.floor(result.time/60)}:${String(Math.floor(result.time%60)).padStart(2,'0')}</b></span><span>ABATES <b>${result.kills}</b></span><span>FERRO <b>${result.scrap}</b></span><span>NÍVEL <b>${result.level}</b></span></div><button class="primary-button" id="resultGarage"><span>VOLTAR AO HANGAR</span><b>↗</b></button><button class="secondary-button" id="resultAgain">NOVA EXPEDIÇÃO</button>`;setHidden($('#overlay'),false);$('#resultGarage').onclick=()=>{setHidden($('#overlay'),true);cleanupRun();setHidden($('#topbar'),false);showScreen('menu');refreshProfile()};$('#resultAgain').onclick=()=>{setHidden($('#overlay'),true);startRun()};$('#bossHud').classList.add('hidden')}
function togglePause(){if(!run||!$('#upgradeScreen').classList.contains('hidden'))return;paused=!paused;if(paused){$('#overlayCard').innerHTML='<span class="section-kicker">EXPEDIÇÃO EM ANDAMENTO</span><h2>PAUSA.</h2><p>O deserto espera. Respire fundo, piloto.</p><button class="primary-button" id="resumeButton"><span>RETOMAR EXPEDIÇÃO</span><b>↗</b></button><button class="secondary-button" id="pauseGarage">ABANDONAR</button>';setHidden($('#overlay'),false);$('#resumeButton').onclick=()=>{paused=false;setHidden($('#overlay'),true)};$('#pauseGarage').onclick=()=>{setHidden($('#overlay'),true);cleanupRun();setHidden($('#topbar'),false);showScreen('menu');refreshProfile()}}else setHidden($('#overlay'),true)}
function openGarage(){previewVehicle=profile.vehicle||0;refreshProfile();showScreen('garage');setHidden($('#topbar'),false)}
function home(){if(run){togglePause();return}showScreen('menu');setHidden($('#topbar'),false)}
