cd /home/runner/work/PlayGround/PlayGround && node - <<'NODE'
const { chromium } = require('playwright');
(async() => {
  const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
  const page = await browser.newPage({viewport:{width:1440,height:1100},deviceScaleFactor:1});
  const pageErrors=[];
  const consoleErrors=[];
  page.on('pageerror', e => pageErrors.push(String(e)));
  page.on('console', msg => { if (msg.type()==='error') consoleErrors.push(msg.text()); });
  await page.goto('http://localhost:5173/', {waitUntil:'networkidle'});
  await page.waitForTimeout(2500);
  console.log('PAGE_ERRORS', pageErrors.length ? pageErrors : 'NONE');
  console.log('CONSOLE_ERRORS', consoleErrors.length ? consoleErrors : 'NONE');
  console.log('TITLE', await page.title());
  const bodyText = await page.locator('body').innerText();
  console.log('BODY_SNIPPET', bodyText.slice(0,200).replace(/\n/g,' | '));
  await browser.close();
})();
NODE
